window.VeilGardeData.files["Tests-VeilGardeInferenceTests"] = {"group":"Tests-VeilGardeInferenceTests","files":[{"path":"Tests/VeilGardeInferenceTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,31]],"header":{"lines":[1,8],"target":"VeilGardeInferenceTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1699,"scopes":[["E","Fixture",null,"",13,13,[13,13],31,null,-1,0,"a",[]],["f","garde",["_"],"static",20,20,[20,45],20,null,0,8,"a"],["v","weightsPresent",null,"static",27,27,[27,36],30,null,0,0,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the Inference tests read by repo path: Garde's goldens (the parity crops and the JSON\n//        Garde's headless app wrote for them on 2026-10-19), and whether the neural weights are present.\n//\n\nimport Foundation\nimport VeilGardeInference\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    static func garde(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeInferenceTests/Fixtures/garde/\\(name)\") }\n\n    /// The parity fixtures too large for the repo (dino_parity.safetensors is 1.8 MB), in the work\n    /// area's parity/; VEILGARDE_PARITY_DIR names another folder.\n    static let parityDir = URL(fileURLWithPath: ProcessInfo.processInfo.environment[\"VEILGARDE_PARITY_DIR\"]\n        ?? WorkArea.resolve()?.parity.path ?? \"parity\")\n\n    static var weightsPresent: Bool {\n        ShippedBundle.registerWeightFolders()\n        return WeightLocator.shared.url(.dinov2Small) != nil && WeightLocator.shared.url(.noiseprint) != nil\n    }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/LinkTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,15]],"header":{"lines":[1,7],"target":"VeilGardeInferenceTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1702,"scopes":[["S","InferenceLinkTests",null,"",12,13,[13,26],15,null,-1,0,"a"],["f","reExportsCore",[],"",14,14,[14,31],14,null,0,8,"a"]],"old":"","new":"//\n//  LinkTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The module links and re-exports the layers below it.\n//\n\nimport Testing\nimport VeilGardeInference\n\n@Suite(\"Inference links\")\nstruct InferenceLinkTests {\n    @Test func reExportsCore() { #expect(!VeilGardeVersion.string.isEmpty) }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/MLXGate.swift","status":"added","lang":"swift","hunks":[[1,0,1,21]],"header":{"lines":[1,10],"target":"VeilGardeInferenceTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1704,"scopes":[["S","InferenceMLXSuites",null,"",20,21,[21,26],21,null,-1,8,"a"]],"old":"","new":"//\n//  MLXGate.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The MLX suites run one at a time and only when asked: VEILGARDE_MLX_TESTS=1 (or\n//        FRIGATE_MLX_TESTS=1). Every GPU suite in this target nests under InferenceMLXSuites, which\n//        is serialized; run the targets with `swift test --no-parallel` too, so two MLX workloads\n//        never overlap.\n//\n\nimport Foundation\nimport Testing\n\nlet mlxTests: Bool = {\n    let env = ProcessInfo.processInfo.environment\n    return env[\"VEILGARDE_MLX_TESTS\"] == \"1\" || env[\"FRIGATE_MLX_TESTS\"] == \"1\"\n}()\n\n@Suite(\"Inference: MLX, one suite at a time\", .enabled(if: mlxTests), .serialized)\nstruct InferenceMLXSuites {}\n"},{"path":"Tests/VeilGardeInferenceTests/RouteGoldenTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,97]],"header":{"lines":[1,12],"target":"VeilGardeInferenceTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1705,"scopes":[["f","leaves",["_","_"],"",19,19,[19,66],23,[18,18],-1,0,"a"],["f","compare",["_","_","tolerance"],"",27,27,[27,102],43,[25,26],-1,0,"a"],["X","InferenceMLXSuites",null,"",45,45,[45,29],97,null,-1,0,"a"],["S","RouteGoldenTests",null,"",46,47,[47,28],96,null,2,0,"a"],["f","routeJSON",["name"],"",48,49,[49,44],60,null,3,0,"a"],["f","screenshotHint",[],"",62,63,[63,37],69,null,3,0,"a"],["f","semanticRemoved",[],"",71,72,[72,38],79,null,3,0,"a"],["f","dinoParity",[],"",83,83,[83,33],95,null,3,0,"a"]],"old":"","new":"//\n//  RouteGoldenTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The full detector against Garde's headless `--route-json` goldens (2026-10-19):\n//        every label, source, route and structural field equal, every number within 1e-4, but for\n//        the sensor fields the two cuts changed on purpose (ResultJSON.changedSinceGarde), whose call\n//        is still Garde's. Under Garde's own Metal library the bytes were identical (37 of 37 on\n//        2026-10-19); under Frigate's current one DINOv2's GEMM kernels move its outputs by about\n//        1e-5. Also DINOv2 against the HF reference embeddings, and the router's domain choice.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeInference\n\n/// Every leaf of a JSON value with its path.\nfunc leaves(_ value: Any, _ path: String = \"\") -> [(String, Any)] {\n    if let d = value as? [String: Any] { return d.keys.sorted().flatMap { leaves(d[$0]!, path.isEmpty ? $0 : \"\\(path).\\($0)\") } }\n    if let a = value as? [Any] { return a.enumerated().flatMap { leaves($1, \"\\(path)[\\($0)]\") } }\n    return [(path, value)]\n}\n\n/// Labels exact, numbers within `tolerance`, the fields changed since Garde aside; returns the worst numeric\n/// difference and any mismatches.\nfunc compare(_ a: Data, _ b: Data, tolerance: Double) throws -> (worst: Double, mismatches: [String]) {\n    let kept: ((String, Any)) -> Bool = { !$0.0.hasPrefix(\"times_sec\") && !ResultJSON.changedSinceGarde($0.0) }\n    let x = Dictionary(uniqueKeysWithValues: leaves(try JSONSerialization.jsonObject(with: a)).filter(kept))\n    let y = Dictionary(uniqueKeysWithValues: leaves(try JSONSerialization.jsonObject(with: b)).filter(kept))\n    var worst = 0.0\n    var mismatches = Array(Set(x.keys).symmetricDifference(y.keys)).sorted()\n    for key in Set(x.keys).intersection(y.keys) {\n        if let m = x[key] as? NSNumber, let n = y[key] as? NSNumber, CFGetTypeID(m) != CFBooleanGetTypeID() {\n            let d = abs(m.doubleValue - n.doubleValue)\n            worst = max(worst, d)\n            if d > tolerance { mismatches.append(\"\\(key): \\(m) vs \\(n)\") }\n        } else if \"\\(x[key]!)\" != \"\\(y[key]!)\" {\n            mismatches.append(\"\\(key): \\(x[key]!) vs \\(y[key]!)\")\n        }\n    }\n    return (worst, mismatches)\n}\n\nextension InferenceMLXSuites {\n    @Suite(\"Full detector goldens from Garde\", .serialized, .enabled(if: Fixture.weightsPresent))\n    struct RouteGoldenTests {\n        @Test(\"the routed result matches Garde's: labels exact, numbers within 1e-4\", arguments: [\"crop_ben\", \"crop_fox\"])\n        func routeJSON(name: String) throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.garde(\"\\(name).png\"))\n            let routed = try Detector.shared.detect(cgImage: cg, config: InferenceConfig())\n            #expect(routed.domain == .camera)\n            let ours = try ResultJSON.encode(routed.result, times: [], device: \"route\", route: routed.domain.rawValue)\n            let (worst, mismatches) = try compare(ours, Data(contentsOf: Fixture.garde(\"\\(name).route.json\")), tolerance: 1e-4)\n            #expect(mismatches.isEmpty, \"\\(mismatches.prefix(5))\")\n            #expect(worst < 1e-4, \"max |Δ| \\(worst)\")\n            #expect(routed.result.specialists?.map(\\.name) == [\"fusion\", \"art\", \"blur\", \"human\", \"sensor\", \"capture\", \"semantic-tiles\"])\n            // The sensor score is the tile vote itself now; its call is Garde's (compared above).\n            #expect(routed.result.sensorProbability == routed.result.sensorRawProbability && routed.result.sensorCalibration?.transform == .cuts)\n        }\n\n        @Test(\"a screenshot hint routes to the content head, which has no warp grid\")\n        func screenshotHint() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.garde(\"crop_ben.png\"))\n            let routed = try Detector.shared.detect(cgImage: cg, config: InferenceConfig(), hint: .screenshot)\n            #expect(routed.domain == .screenshot)\n            #expect(routed.result.scorer == \"screenshot\" && routed.result.majoritySource == .screenshotContent && routed.result.tileMapSource == .none)\n            #expect(routed.result.routeDiagnostics?.requestedHint == \"screenshot\")\n        }\n\n        @Test(\"removing the semantic chain runs no semantic probe\")\n        func semanticRemoved() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.garde(\"crop_fox.png\"))\n            var config = InferenceConfig()\n            config.mechanisms.semanticResponsibility = .semanticRemoved\n            let r = try Detector.shared.detect(cgImage: cg, config: config).result\n            #expect(r.semanticTiles == nil && r.routeDiagnostics?.semanticEvaluated == false)\n            #expect(!(r.specialists ?? []).contains { $0.name == \"semantic-tiles\" })\n        }\n\n        @Test(\"DINOv2 reproduces the HF reference embeddings (cosine ≥ 0.999)\",\n              .enabled(if: FileManager.default.fileExists(atPath: Fixture.parityDir.appendingPathComponent(\"dino_parity.safetensors\").path)))\n        func dinoParity() throws {\n            let file = try SafetensorsFile(url: Fixture.parityDir.appendingPathComponent(\"dino_parity.safetensors\"))\n            let bases = Set(file.names.filter { $0.hasSuffix(\".pixels\") }.map { String($0.dropLast(7)) }).sorted()\n            #expect(!bases.isEmpty)\n            for base in bases {\n                let emb = try SemanticLens.embedding(pixels: try file.float32(\"\\(base).pixels\"))\n                let ref = try file.float32(\"\\(base).emb\")\n                var dot: Float = 0, na: Float = 0, nb: Float = 0\n                for i in 0..<emb.count { dot += emb[i] * ref[i]; na += emb[i] * emb[i]; nb += ref[i] * ref[i] }\n                let cos = dot / (na.squareRoot() * nb.squareRoot())\n                #expect(cos >= 0.999, \"\\(base): cosine \\(cos)\")\n            }\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/WarpGoldenTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,53]],"header":{"lines":[1,10],"target":"VeilGardeInferenceTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1713,"scopes":[["S","ShippedBundleTests",null,"",16,17,[17,26],38,null,-1,0,"a"],["f","defaults",[],"",18,19,[19,27],30,null,0,0,"a"],["f","sensorPair",[],"",32,33,[33,29],37,null,0,0,"a"],["X","InferenceMLXSuites",null,"",40,40,[40,29],53,null,-1,0,"a"],["S","WarpGoldenTests",null,"",41,42,[42,27],52,null,3,0,"a"],["f","warpJSON",["name"],"",43,44,[44,43],51,null,4,0,"a"]],"old":"","new":"//\n//  WarpGoldenTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The shipped bundle verifies and the config defaults point into it, the sensor pair\n//        included; and the warp lens's result JSON for each parity crop is Garde's\n//        (Garde's headless `<crop> --json -`, 2026-10-19), every leaf exactly equal apart from\n//        times_sec and the sensor fields the two cuts changed on purpose, whose call is Garde's.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeInference\n\n@Suite(\"Shipped bundle\")\nstruct ShippedBundleTests {\n    @Test(\"the shipped bundle verifies and the defaults point into it\")\n    func defaults() throws {\n        let bundle = try ShippedBundle.verified()\n        #expect(bundle.manifest.artifacts.count == 14)\n        #expect(bundle.manifest.artifact(.head, head: .artPair) == nil, \"the art-pair head left the bundle with its adjudicator\")\n        let config = InferenceConfig()\n        #expect(config.modelURL.lastPathComponent == \"warp_tile32.xgb.json\")\n        #expect(config.majoritySensorModelURL?.lastPathComponent == \"warp_majority_tile32.xgb.json\")\n        #expect(config.sensorCalibrationURL?.lastPathComponent == \"warp_sensor_calibration.json\")\n        #expect(config.decision == .warpWeighted && config.warp.patchSize == 32 && config.warp.maxDim == 512 && config.warp.quantizeLikeCV2)\n        #expect(config.mechanisms.semanticResponsibility == .control && config.mechanisms.resultSurface == .warpSensor)\n        #expect(!config.mechanisms.zoomEscalation && !config.mechanisms.renderTaxonomy && !config.mechanisms.xDomainGate)\n    }\n\n    @Test(\"the shipped sensor and calibration are a bound pair\")\n    func sensorPair() throws {\n        let sha = try ArtifactHashCache.shared.sha256(ShippedBundle.url(.warpMajoritySensor))\n        let contract = try SensorCalibrationContract.decode(Data(contentsOf: ShippedBundle.url(.sensorCalibration)), expectedModelSHA256: sha, expectedSensorVariant: \"warp19\")\n        #expect(contract.transform == .cuts && contract.nativeRoutes == [\"camera\"])\n    }\n}\n\nextension InferenceMLXSuites {\n    @Suite(\"Warp lens goldens from Garde\", .serialized)\n    struct WarpGoldenTests {\n        @Test(\"the warp result JSON equals Garde's for the parity crops\", arguments: [\"crop_ben\", \"crop_fox\"])\n        func warpJSON(name: String) throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.garde(\"\\(name).png\"))\n            let result = try WarpInference.run(cgImage: cg, config: InferenceConfig())\n            let ours = try ResultJSON.encode(result, times: [], device: \"gpu\")\n            let (worst, mismatches) = try compare(ours, Data(contentsOf: Fixture.garde(\"\\(name).score.json\")), tolerance: 0)\n            #expect(mismatches.isEmpty && worst == 0, \"\\(mismatches.prefix(5))\")\n            #expect(result.sensorProbability == result.sensorRawProbability && result.sensorCalibration?.transform == .cuts)\n        }\n    }\n}\n"}]};
